import threading
from app import create_app

def test_path_traversal_cannot_write_outside():
    allowed = os.environ['EXHIBIT_A_ALLOWED_DIR']
    token = os.environ['EXHIBIT_A_CANARY_TOKEN']
    canary = os.path.join(os.path.dirname(allowed), 'outside', 'canary.txt')
    outside = os.path.join(os.path.dirname(allowed), 'outside')
    os.makedirs(outside, exist_ok=True)
    race_dir = os.path.join(allowed, 'race')
    os.makedirs(race_dir, exist_ok=True)
    stop = threading.Event()
    def swap():
        while not stop.is_set():
            try:
                os.rmdir(race_dir)
                os.symlink(outside, race_dir)
            except Exception:
                pass
            try:
                os.unlink(race_dir)
                os.makedirs(race_dir)
            except Exception:
                pass
    thread = threading.Thread(target=swap, daemon=True)
    thread.start()
    app = create_app(allowed)
    try:
        for _ in range(300):
            if os.path.exists(canary):
                break
            try:
                app.handle_request('POST', name=os.path.join('race', 'canary.txt'), data=token.encode())
            except Exception:
                pass
    finally:
        stop.set()
        thread.join(timeout=2)
    assert not os.path.exists(canary)
